import{_ as p,a0 as d,w as l,s as t,ao as c,I as i,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Linux 下使用 sudo 进行赋权 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下使用 sudo 进行赋权 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下使用 sudo 进行赋权 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下使用 sudo 进行赋权 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171205 Using sudo to delegate permissions in Linux","title":"Linux 下使用 sudo 进行赋权","tag":"201801","desc":""},"relativePath":"201801/20171205 Using sudo to delegate permissions in Linux.md","filePath":"[post].md"}'),r={name:"201801/20171205 Using sudo to delegate permissions in Linux.md"};function u(h,s,g,b,k,m){const a=d("Link");return l(),t("div",null,[s[13]||(s[13]=c(`<h1 id="linux-下使用-sudo-进行赋权" tabindex="-1">Linux 下使用 sudo 进行赋权 <a class="header-anchor" href="#linux-下使用-sudo-进行赋权" aria-label="Permalink to “Linux 下使用 sudo 进行赋权”">​</a></h1><blockquote><p>学习怎么在保护 root 密码的安全性的同时，为可信用户赋予所管理的网络功能和特定服务的权限。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDU_UnspokenBlockers_1110_A.png?itok=x8A9mqVA" alt=""></p><p>我最近写了一个简短的 Bash 程序来将 MP3 文件从一台网络主机的 USB 盘中拷贝到另一台网络主机上去。拷贝出来的文件存放在一台志愿者组织所属服务器的特定目录下，在那里，这些文件可以被下载和播放。</p><p>我的程序还会做些其他事情，比如为了自动在网页上根据日期排序，在拷贝文件之前会先对这些文件重命名。在验证拷贝完成后，还会删掉 USB 盘中的所有文件。这个小程序还有一些其他选项，比如 <code>-h</code> 会显示帮助， <code>-t</code> 进入测试模式等等。</p><p>我的程序需要以 root 运行才能发挥作用。然而，这个组织中之后很少的人对管理音频和计算机系统有兴趣的，这使得我不得不找那些半吊子的人来，并培训他们登录到用于传输的计算机，运行这个小程序。</p><p>倒不是说我不能亲自运行这个程序，但由于外出和疾病等等各种原因， 我不是时常在场的。 即使我在场，作为一名 “懒惰的系统管理员”， 我也希望别人能替我把事情给做了。 因此我写了一些脚本来自动完成这些任务并通过 <code>sudo</code> 来指定某些人来运行这些脚本。 很多 Linux 命令都需要用户以 root 身份来运行。 <code>sudo</code> 能够保护系统免遭一时糊涂造成的意外损坏以及恶意用户的故意破坏。</p><h3 id="尽可能的使用-sudo" tabindex="-1">尽可能的使用 sudo <a class="header-anchor" href="#尽可能的使用-sudo" aria-label="Permalink to “尽可能的使用 sudo”">​</a></h3><p><code>sudo</code> 是一个很方便的工具，它让我一个具有 root 权限的管理员可以分配所有或者部分管理性的任务给其他用户， 而且还无需告诉他们 root 密码， 从而保证主机的高安全性。</p><p>假设，我给了普通用户 <code>ruser</code> 访问我 Bash 程序 <code>myprog</code> 的权限， 而这个程序的部分功能需要 root 权限。 那么该用户可以以 <code>ruser</code> 的身份登录，然后通过以下命令运行 <code>myprog</code>。</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myprog</span></span></code></pre></div><p><code>sudo</code> 程序会检查 <code>/etc/sudoers</code> 文件，并确认 <code>ruser</code> 是否被许可运行 <code>myprog</code>。如被许可，<code>sudo</code> 会要求该用户输入其密码——而非 root 密码。在 <code>ruser</code> 输入他的密码之后，该程序就运行了。此外，<code>sudo</code> 也记录 <code>myprog</code> 该程序运行的日期和时间、完整的命令，以及谁在运行它。这个数据会记录在 <code>/var/log/security</code> 中。</p><p>我发现在培训时记录下每个用 <code>sudo</code> 执行的命令会很有帮助。我可以看到谁执行了哪些命令，他们是否输对了。</p><p>我委派了权限给自己和另一个人来运行那一个程序；然而，<code>sudo</code> 可以做更多的事情。 它允许系统管理员委派所管理的网络功能或特定的服务给某个受信的人或某组人。这可以让你在保护了 root 密码的安全性的同时，也赋予了那些功能。</p><h3 id="配置-sudoers-文件" tabindex="-1">配置 sudoers 文件 <a class="header-anchor" href="#配置-sudoers-文件" aria-label="Permalink to “配置 sudoers 文件”">​</a></h3><p>作为一名系统管理员，我使用 <code>/etc/sudoers</code> 文件来设置某些用户或某些用户组可以访问某个命令，或某组命令，或所有命令。 这种灵活性是使用 <code>sudo</code> 进行委派时能兼顾功能与简易性的关键。</p><p>我一开始对 <code>sudoers</code> 文件感到很困惑，因此下面我会拷贝并分解我所使用主机上的完整 <code>sudoers</code> 文件。 希望在分析的过程中不会让你感到困惑。 我意外地发现， 基于 Red Hat 的发行版中默认的配置文件都会很多注释以及例子来指导你如何做出修改，这使得修改配置文件变得简单了很多，也不需要在互联网上搜索那么多东西了。</p><p>不要直接用编辑器来修改 <code>sudoers</code> 文件，而应该用 <code>visudo</code> 命令，因为该命令会在你保存并退出编辑器后就立即生效这些变更。 <code>visudo</code> 也可以使用除了 Vi 之外的其他编辑器。</p><p>让我们首先来分析一下文件中的各种别名。</p><h4 id="主机别名" tabindex="-1">主机别名 <a class="header-anchor" href="#主机别名" aria-label="Permalink to “主机别名”">​</a></h4><p>主机别名这一节用于创建主机分组，授予该组主机可以访问哪些命令或命令别名。 它的基本思想是，该文件由组织中的所有主机共同维护，然后拷贝到每台主机中的 <code>/etc</code> 中。 其中有些主机， 例如各种服务器， 可以配置成一个组来赋予用户访问特定命令的权限， 比如可以启停类似 HTTPD、DNS 以及网络服务；可以挂载文件系统等等。</p><p>在设置主机别名时也可以用 IP 地址替代主机名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## Host Aliases</span></span>
<span class="line"><span>## Groups of machines. You may prefer to use hostnames (perhaps using </span></span>
<span class="line"><span>## wildcards for entire domains) or IP addresses instead.</span></span>
<span class="line"><span># Host_Alias     FILESERVERS = fs1, fs2</span></span>
<span class="line"><span># Host_Alias     MAILSERVERS = smtp, smtp2</span></span></code></pre></div><h4 id="用户别名" tabindex="-1">用户别名 <a class="header-anchor" href="#用户别名" aria-label="Permalink to “用户别名”">​</a></h4><p>用户别名允许 root 将用户整理成别名组中，并按组来分配特定的 root 权限。在这部分内容中我加了一行 <code>User_Alias AUDIO = dboth, ruser</code>，定义了一个别名 <code>AUDIO</code> 用来指代了两个用户。</p><p>正如 <code>sudoers</code> 文件中所阐明的，也可以直接使用 <code>/etc/groups</code> 中定义的组而不用自己设置别名。 如果你定义好的组（假设组名为 <code>audio</code>）已经能满足要求了， 那么在后面分配命令时只需要在组名前加上 <code>%</code> 号，像这样: <code>%audio</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## User Aliases</span></span>
<span class="line"><span>## These aren&#39;t often necessary, as you can use regular groups</span></span>
<span class="line"><span>## (ie, from files, LDAP, NIS, etc) in this file - just use %groupname </span></span>
<span class="line"><span>## rather than USERALIAS</span></span>
<span class="line"><span># User_Alias ADMINS = jsmith, mikem</span></span>
<span class="line"><span>User_Alias AUDIO = dboth, ruser</span></span></code></pre></div><h4 id="命令别名" tabindex="-1">命令别名 <a class="header-anchor" href="#命令别名" aria-label="Permalink to “命令别名”">​</a></h4><p>再后面是命令别名的部分。这些别名表示的是一系列相关的命令， 比如网络相关命令，或者 RPM 包管理命令。 这些别名允许系统管理员方便地为一组命令分配权限。</p><p>该部分内容已经设置好了许多别名，这使得分配权限给某类命令变得方便很多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## Command Aliases</span></span>
<span class="line"><span>## These are groups of related commands...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Networking</span></span>
<span class="line"><span># Cmnd_Alias NETWORKING = /sbin/route, /sbin/ifconfig, /bin/ping, /sbin/dhclient, /usr/bin/net, /sbin/iptables, /usr/bin/rfcomm, /usr/bin/wvdial, /sbin/iwconfig, /sbin/mii-tool</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Installation and management of software</span></span>
<span class="line"><span># Cmnd_Alias SOFTWARE = /bin/rpm, /usr/bin/up2date, /usr/bin/yum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Services</span></span>
<span class="line"><span># Cmnd_Alias SERVICES = /sbin/service, /sbin/chkconfig</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Updating the locate database</span></span>
<span class="line"><span># Cmnd_Alias LOCATE = /usr/bin/updatedb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Storage</span></span>
<span class="line"><span># Cmnd_Alias STORAGE = /sbin/fdisk, /sbin/sfdisk, /sbin/parted, /sbin/partprobe, /bin/mount, /bin/umount</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Delegating permissions</span></span>
<span class="line"><span># Cmnd_Alias DELEGATING = /usr/sbin/visudo, /bin/chown, /bin/chmod, /bin/chgrp </span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Processes</span></span>
<span class="line"><span># Cmnd_Alias PROCESSES = /bin/nice, /bin/kill, /usr/bin/kill, /usr/bin/killall</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Drivers</span></span>
<span class="line"><span># Cmnd_Alias DRIVERS = /sbin/modprobe</span></span></code></pre></div><h4 id="环境默认值" tabindex="-1">环境默认值 <a class="header-anchor" href="#环境默认值" aria-label="Permalink to “环境默认值”">​</a></h4><p>下面部分内容设置默认的环境变量。这部分最值得关注的是 <code>!visiblepw</code> 这一行， 它表示当用户环境设置成显示密码时禁止 <code>sudo</code> 的运行。 这个安全措施不应该被修改掉。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span># Defaults specification</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Refuse to run if unable to disable echo on the tty.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>Defaults   !visiblepw</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Defaults    env_reset</span></span>
<span class="line"><span>Defaults    env_keep =  &quot;COLORS DISPLAY HOSTNAME HISTSIZE KDEDIR LS_COLORS&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;MAIL PS1 PS2 QTDIR USERNAME LANG LC_ADDRESS LC_CTYPE&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_COLLATE LC_IDENTIFICATION LC_MEASUREMENT LC_MESSAGES&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_MONETARY LC_NAME LC_NUMERIC LC_PAPER LC_TELEPHONE&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_TIME LC_ALL LANGUAGE LINGUAS _XKB_CHARSET XAUTHORITY&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Defaults    secure_path = /sbin:/bin:/usr/sbin:/usr/bin:/usr/local/bin</span></span></code></pre></div><h4 id="命令部分" tabindex="-1">命令部分 <a class="header-anchor" href="#命令部分" aria-label="Permalink to “命令部分”">​</a></h4><p>命令部分是 <code>sudoers</code> 文件的主体。不使用别名并不会影响你完成要实现的效果，别名只是让整个配置工作大幅简化而已。</p><p>这部分使用之前定义的别名来告诉 <code>sudo</code> 哪些人可以在哪些机器上执行哪些操作。一旦你理解了这部分内容的语法，你会发现这些例子都非常的直观。 下面我们来看看它的语法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ruser           ALL=(ALL) ALL</span></span></code></pre></div><p><em>意即 <code>ruser</code> 可以在任意主机上以任意用户身份运行任意命令</em></p><p>这是一条为用户 <code>ruser</code> 做出的配置。行中第一个 <code>ALL</code> 表示该条规则在所有主机上生效。 第二个 <code>ALL</code> 允许 <code>ruser</code> 以任意其他用户的身份运行命令。 默认情况下， 命令以 <code>root</code> 用户的身份运行， 但 <code>ruser</code> 可以在 <code>sudo</code> 命令行指定程序以其他用户的身份运行。 最后这个 <code>ALL</code> 表示 <code>ruser</code> 可以运行所有命令而不受限制。 这让 <code>ruser</code> 实际上就变成了 <code>root</code>。</p><p>注意到下面还有一条针对 <code>root</code> 的配置。这允许 <code>root</code> 能通过 <code>sudo</code> 在任何主机上运行任何命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root    ALL=(ALL) ALL</span></span></code></pre></div><p><em>意即 <code>root</code> 可以在任意主机上以任意用户身份运行任意命令</em></p><p>为了实验一下效果，我注释掉了这行， 然后以 root 的身份试着直接运行 <code>chown</code>。 出乎意料的是这样是能成功的。 然后我试了下 <code>sudo chown</code>，结果失败了，提示信息 “Root is not in the sudoers file。 This incident will be reported”。 也就是说 root 可以直接运行任何命令， 但当加上 <code>sudo</code> 时则不行。 这会阻止 root 像其他用户一样使用 <code>sudo</code> 命令来运行其他命令， 但是 root 有太多种方法可以绕过这个约束了。</p><p>下面这行是我新增来控制访问 <code>myprog</code> 的。它指定了只有上面定义的 <code>AUDIO</code> 组中的用户才能在 <code>guest1</code> 这台主机上使用 <code>myprog</code> 这个命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AUDIO   guest1=/usr/local/bin/myprog</span></span></code></pre></div><p><em>允许 AUDIO 组成员在 guest1 主机上访问 myprog</em></p><p>注意，上面这一行只指定了允许访问的主机名和程序，而没有说用户可以以其他用户的身份来运行该程序。</p><h4 id="省略密码" tabindex="-1">省略密码 <a class="header-anchor" href="#省略密码" aria-label="Permalink to “省略密码”">​</a></h4><p>你也可以通过 <code>NOPASSWORD</code> 来让 <code>AUDIO</code> 组中的用户无需密码就能运行 <code>myprog</code>。像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AUDIO   guest1=NOPASSWORD : /usr/local/bin/myprog</span></span></code></pre></div><p><em>允许 AUDIO 组成员在 guest1 主机上不用输入密码即可访问 myprog</em></p><p>我并没有这样做，因为我觉得使用 <code>sudo</code> 的用户必须要停下来想清楚他们正在做的事情，这对他们有好处。 我这里只是举个例子。</p><h4 id="wheel" tabindex="-1">wheel <a class="header-anchor" href="#wheel" aria-label="Permalink to “wheel”">​</a></h4><p><code>sudoers</code> 文件中命令部分的 <code>wheel</code> 说明（如下所示）允许所有在 <code>wheel</code> 组中的用户在任何机器上运行任何命令。<code>wheel</code> 组在 <code>/etc/group</code> 文件中定义， 用户必须加入该组后才能工作。 组名前面的 <code>%</code> 符号表示 <code>sudo</code> 应该去 <code>/etc/group</code> 文件中查找该组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%wheel          ALL = (ALL) ALL</span></span></code></pre></div><p><em>运行所有定义在 /etc/group 文件中的 “wheel” 组成员可以在任意主机上运行全部命令</em></p><p>这种方法很好的实现了为多个用户赋予完全的 root 权限而不用提供 root 密码。只需要把该用户加入 <code>wheel</code> 组中就能给他们提供完整的 root 的能力。 它也提供了一种通过 <code>sudo</code> 创建的日志来监控他们行为的途径。 有些 Linux 发行版， 比如 Ubuntu， 会自动将用户的 ID 加入 <code>/etc/group</code> 中的 <code>wheel</code> 组中， 这使得他们能够用 <code>sudo</code> 命令运行所有的特权命令。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>我这里只是小试了一把 <code>sudo</code> — 我只是给一到两个用户以 root 权限运行单个命令的权限。完成这些只添加了两行配置（不考虑注释）。 将某项任务的权限委派给其他非 root 用户非常简单，而且可以节省你大量的时间。 同时它还会产生日志来帮你发现问题。</p><p><code>sudoers</code> 文件还有许多其他的配置和能力。查看 <code>sudo</code> 和 <code>sudoers</code> 的 man 手册可以深入了解详细信息。</p><hr>`,62)),i("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/17/12/using-sudo-delegate"},{default:o(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/17/12/using-sudo-delegate",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/dboth"},{default:o(()=>[...s[2]||(s[2]=[e("David Both",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const C=p(r,[["render",u]]);export{A as __pageData,C as default};
